statement:
A train line has stops numbered `0` to `n`, and every pair of neighbouring stops is joined by two tracks: a regular one and an express one. Riding from stop `i` to stop `i + 1` costs `regular[i]` on the regular track and `express[i]` on the express track (both arrays have length `n` and are indexed from 0 here).

You start at stop `0` on the regular track. At any stop you may change tracks, as often as you like:

- going from the regular track to the express track costs `expressCost` every time you do it;
- going from the express track back to the regular track is free;
- staying on the express track costs nothing beyond its fares.

Return an array `costs` of length `n` in which `costs[i]` is the smallest total amount needed to arrive at stop `i + 1` from stop `0`. A stop counts as reached whichever track you arrive on.

validator:
function validate([regular, express, expressCost]) {
  if (!Array.isArray(regular) || !Array.isArray(express)) return 'regular and express must be arrays.';
  if (regular.length < 1 || regular.length > 100000) return 'regular needs 1 to 10^5 fares.';
  if (express.length !== regular.length) return 'regular and express must have the same length.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 100000;
  if (!regular.every(ok) || !express.every(ok)) return 'Every fare is an integer from 1 to 10^5.';
  if (!ok(expressCost)) return 'expressCost is an integer from 1 to 10^5.';
  return null;
}

reference:
function minimumCosts(regular, express, expressCost) {
  const n = regular.length;
  const costs = new Array(n);
  let onRegular = 0;
  let onExpress = expressCost;

  for (let i = 0; i < n; i++) {
    const byRegular = onRegular + regular[i];
    const byExpress = onExpress + express[i];
    onRegular = Math.min(byRegular, byExpress);
    onExpress = Math.min(byExpress, byRegular + expressCost);
    costs[i] = Math.min(onRegular, onExpress);
  }
  return costs;
}

