function minimumCosts(regular, express, expressCost) {
  // Try every choice of track for every segment up to each stop and price it directly.
  const n = regular.length;
  const answer = [];
  for (let stop = 1; stop <= n; stop++) {
    let best = Infinity;
    for (let mask = 0; mask < (1 << stop); mask++) {
      let total = 0;
      for (let seg = 0; seg < stop; seg++) {
        const fast = (mask >> seg) & 1;
        const prevFast = seg > 0 ? (mask >> (seg - 1)) & 1 : 0;
        if (fast && !prevFast) total += expressCost;
        total += fast ? express[seg] : regular[seg];
      }
      best = Math.min(best, total);
    }
    answer.push(best);
  }
  return answer;
}

