function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const regular = Array.from({ length: n }, () => int(1, 100000));
    const express = Array.from({ length: n }, () => int(1, 100000));
    return [regular, express, int(1, 100000)];
  }
  const n = int(1, 9);
  const top = rand() < 0.5 ? 5 : 30;
  const regular = Array.from({ length: n }, () => int(1, top));
  const express = Array.from({ length: n }, () => int(1, top));
  return [regular, express, int(1, top * 2)];
}
